def is_decimal(value) -> bool:
    s = str(value)
    if s.startswith('-'):
        s = s[1:]
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if not integer_part.isdigit():
        return False
    if len(decimal_part) != 2 or not decimal_part.isdigit():
        return False
    return True

def is_Two_Alter(s: str) -> bool:
    if len(s) == 0:
        return False
    if len(s) == 1:
        return True

    distinct_chars = set(s)
    if len(distinct_chars) > 2:
        return False

    # Check if characters alternate
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True

def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for num in arr[1:]:
        max_ending_here = max(num, max_ending_here + num)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

